canonical_solution:
{
  List<Integer> result = new ArrayList<>();
  for (int i = 1; i < 10; i++) { // start with all numbers from 1 to 9
    dfs(i, n, result);
  }
  return result;
}

private static void dfs(int current, int n, List<Integer> result) {
  if (current > n) {
    return; // stop the recursion if current is greater than n
  }
  result.add(current); // add current number to the result list
  for (int i = 0; i < 10; i++) { // traverse the next digit
    if (10 * current + i > n) {
      return; // stop if the next number is greater than n
    }
    dfs(10 * current + i, n, result); // recurse with next number
  }
}

